SELECT ''=========================================='' AS '''';
SELECT ''RESUMEN FINAL DE VALIDACIONES'' AS '''';
SELECT ''=========================================='' AS '''';

SELECT '''' AS '''';
SELECT ''1. Total de turnos creados en pruebas:'' AS '''';
SELECT COUNT\(*\) AS cantidad FROM turnos WHERE empleado_id IN \(1, 999\);

SELECT '''' AS '''';
SELECT ''2. Turnos por tipo:'' AS '''';
SELECT tipo_turno, COUNT\(*\) AS cantidad 
FROM turnos 
WHERE empleado_id IN \(1, 999\) 
GROUP BY tipo_turno;

SELECT '''' AS '''';
SELECT ''3. Turnos en feriados:'' AS '''';
SELECT COUNT\(*\) AS cantidad 
FROM turnos 
WHERE empleado_id IN \(1, 999\) AND es_feriado = TRUE;

SELECT '''' AS '''';
SELECT ''4. Validación de límites \(NO deben existir turnos inválidos\):'' AS '''';
SELECT 
  CASE 
    WHEN COUNT\(*\) = 0 THEN ''CORRECTO - Trigger funcionando''
    ELSE CONCAT\(''ERROR - '', COUNT\(*\), '' turnos inválidos''\)
  END AS resultado
FROM turnos 
WHERE empleado_id IN \(1, 999\) 
  AND \(horas_normales > 12 OR horas_extras > 4 OR \(horas_normales + horas_extras\) > 16\);

SELECT '''' AS '''';
SELECT ''5. Turno con límite máximo permitido \(12h + 4h = 16h\):'' AS '''';
SELECT COUNT\(*\) AS cantidad 
FROM turnos 
WHERE empleado_id IN \(1, 999\) 
  AND horas_normales = 12 AND horas_extras = 4;
